import{i as e,r as t,s as n,t as r}from"./app-zOyjnCdX.js";import"./bundle-item-search-6ZZHNyfZ.js";import"./bundle-optional-items-Z5g-bzEh.js";var i=JSON.parse(`{"path":"/product-bundle/examples.html","title":"Practical Examples","lang":"en-US","frontmatter":{"title":"Practical Examples"},"git":{},"filePathRelative":"product-bundle/examples.md"}`),a={name:`examples.md`};function o(r,i,a,o,s,c){return n(),t(`div`,null,[...i[0]||=[e(`<h1 id="practical-examples" tabindex="-1"><a class="header-anchor" href="#practical-examples"><span>Practical Examples</span></a></h1><p>Four proven configurations you can copy. Each lists the exact Bundle Items tab values and what the customer will experience.</p><h2 id="_1-package-deal-at-a-headline-price" tabindex="-1"><a class="header-anchor" href="#_1-package-deal-at-a-headline-price"><span>1. Package deal at a headline price</span></a></h2><p><em>&quot;The complete home electronics kit — $5,999.&quot;</em></p><table><thead><tr><th>Setting</th><th>Value</th></tr></thead><tbody><tr><td>Bundle Pricing Mode</td><td><strong>Fixed Bundle Price</strong></td></tr><tr><td>Bundle Fixed Price</td><td><code>5999</code></td></tr><tr><td>Enable Bundle Discount</td><td>off</td></tr><tr><td>Compulsory Items Count</td><td>empty (all mandatory)</td></tr><tr><td>Items</td><td>Washing Machine ×1, iPhone ×1, MacBook ×1, LED TV ×1</td></tr></tbody></table><p>Customer sees a flat <strong>$5,999.00</strong>, all four items listed without checkboxes, one decision to make: how many kits.</p><p><img src="/bundle-products-for-woocommerce/images/product-bundle/bundle-fixed-price-page.webp" alt="Fixed-price package deal"></p><h2 id="_2-pick-and-mix-kit-with-savings" tabindex="-1"><a class="header-anchor" href="#_2-pick-and-mix-kit-with-savings"><span>2. Pick-and-mix kit with savings</span></a></h2><p><em>&quot;Start with the washing machine, add what you like — save 10% on everything.&quot;</em></p><table><thead><tr><th>Setting</th><th>Value</th></tr></thead><tbody><tr><td>Bundle Pricing Mode</td><td><strong>Dynamic Bundle Price</strong></td></tr><tr><td>Enable Bundle Discount</td><td>on — Percentage (%), value <code>10</code></td></tr><tr><td>Compulsory Items Count</td><td><code>1</code></td></tr><tr><td>Max Purchase Limit</td><td><code>10</code></td></tr><tr><td>Items</td><td>Washing Machine ×1 (first), then iPhone ×1, MacBook ×1, LED TV ×1</td></tr></tbody></table><p>Catalog shows &quot;<strong>From:</strong> <s>$1,300.00</s> $1,170.00&quot;. On the page the customer ticks extras and watches <strong>Bundle Total</strong> and <strong>You Save</strong> update live. This is exactly the live demo&#39;s configuration.</p><p><img src="/bundle-products-for-woocommerce/images/product-bundle/bundle-optional-items.webp" alt="Pick-and-mix with live totals"></p><h2 id="_3-starter-pack-with-consumables" tabindex="-1"><a class="header-anchor" href="#_3-starter-pack-with-consumables"><span>3. Starter pack with consumables</span></a></h2><p><em>&quot;Contractor starter kit: one drill, one helmet, two pairs of gloves.&quot;</em></p><table><thead><tr><th>Setting</th><th>Value</th></tr></thead><tbody><tr><td>Bundle Pricing Mode</td><td>Dynamic Bundle Price</td></tr><tr><td>Enable Bundle Discount</td><td>on — Percentage (%), value <code>10</code></td></tr><tr><td>Compulsory Items Count</td><td><code>1</code></td></tr><tr><td>Items</td><td>Cordless Drill Kit ×1, Safety Helmet ×1, Work Gloves Pair <strong>×2</strong></td></tr></tbody></table><p>The per-item <strong>Quantity</strong> column does the work: every kit that includes the gloves includes <strong>two pairs</strong>, priced accordingly in the dynamic total.</p><h2 id="_4-limited-offer-with-exact-variations" tabindex="-1"><a class="header-anchor" href="#_4-limited-offer-with-exact-variations"><span>4. Limited offer with exact variations</span></a></h2><p><em>&quot;Weekend deal — max 2 per order, includes the black hoodie in size L.&quot;</em></p><table><thead><tr><th>Setting</th><th>Value</th></tr></thead><tbody><tr><td>Bundle Pricing Mode</td><td>Fixed Bundle Price</td></tr><tr><td>Enable Bundle Discount</td><td>on — Fixed Amount, e.g. <code>20</code></td></tr><tr><td>Max Purchase Limit</td><td><code>2</code></td></tr><tr><td>Items</td><td>search returns variations too — pick <em>Brown hoodie – Black, Large (L)</em> directly</td></tr></tbody></table><p><img src="/bundle-products-for-woocommerce/images/product-bundle/bundle-item-search.webp" alt="Variation search in the items table"></p><p>The variation is always part of the kit (variations can&#39;t be optional), the discount shows as a struck-through price, and a third kit in one order is refused with the purchase-limit message.</p><div class="hint-container tip"><p class="hint-container-title">Mix the mechanics freely</p><p>Pricing mode, discount, compulsory count, per-item quantities and the purchase limit are independent switches — any combination is valid.</p></div>`,22)]])}var s=r(a,[[`render`,o]]);export{i as _pageData,s as default};